1	/**
2	 * Port of `whoosh.analysis.analyzers`.
3	 *
4	 * An analyzer is just a tokenizer followed by zero or more filters, wired into
5	 * one lazy generator chain. In Whoosh these are built with the `|` operator
6	 * (`RegexTokenizer() | LowercaseFilter() | StopFilter()`), which produces a
7	 * `CompositeAnalyzer`; here the composition is explicit.
8	 *
9	 * CANONICAL ENTRY POINT: `analyzer.analyze(value, opts)` -> Iterable<Token>.
10	 * `analyzer.call(value, opts)` is an alias with identical behaviour, provided
11	 * because Whoosh's analyzers are callable objects and the alias keeps ported call
12	 * sites readable.
13	 *
14	 * Note that `StandardAnalyzer` and friends are FUNCTIONS, not classes, in Whoosh
15	 * too - they are composition helpers that return a `CompositeAnalyzer`.
16	 */
17	
18	import { Token } from './token.mjs';
19	import { STOP_WORDS } from './stopwords.mjs';
20	import {
21	  DEFAULT_WORD_PATTERN,
22	  IDTokenizer,
23	  RegexTokenizer,
24	  SpaceSeparatedTokenizer,
25	} from './tokenizers.mjs';
26	import { LowercaseFilter, StopFilter } from './filters.mjs';
27	
28	/**
29	 * Base class for analyzers (Whoosh's `Analyzer`, a `Composable`).
30	 *
31	 * The base analyzes to nothing; concrete analyzers override `analyze()`.
32	 */
33	export class Analyzer {
34	  /**
35	   * @param {unknown} _value the field value to analyze
36	   * @param {object} [_opts] pipeline options: `{positions, chars, start_pos,
37	   *   start_char, mode, removestops, keeporiginal, tokenize}`
38	   * @returns {Generator<Token>}
39	   */
40	  // eslint-disable-next-line no-unused-vars
41	  *analyze(_value, _opts = {}) {
42	    // Abstract: no pipeline configured.
43	  }
44	
45	  /**
46	   * Alias for {@link Analyzer#analyze} (Whoosh analyzers are callable).
47	   * @param {unknown} value
48	   * @param {object} [opts]
49	   * @returns {Iterable<Token>}
50	   */
51	  call(value, opts = {}) {
52	    return this.analyze(value, opts);
53	  }
54	
55	  /** Whoosh's `Composable.clean()` hook. */
56	  clean() {}
57	
58	  /** Whoosh's `has_morph()`: true if any stage does stemming/morphology. */
59	  has_morph() {
60	    return false;
61	  }
62	}
63	
64	/**
65	 * Port of `whoosh.analysis.analyzers.CompositeAnalyzer`.
66	 *
67	 * Holds a tokenizer followed by filters and chains them lazily. As in Whoosh, a
68	 * nested CompositeAnalyzer is FLATTENED into this one's item list, so
69	 * `CompositeAnalyzer(StandardAnalyzer(), someFilter)` behaves as a single chain.
70	 */
71	export class CompositeAnalyzer extends Analyzer {
72	  /**
73	   * @param {...(object)} composables a tokenizer first, then filters (or another
74	   *   CompositeAnalyzer, whose items get spliced in)
75	   */
76	  constructor(...composables) {
77	    super();
78	    /** @type {object[]} pipeline stages, in order */
79	    this.items = [];
80	    for (const comp of composables) {
81	      if (!comp) continue;
82	      if (comp instanceof CompositeAnalyzer && Array.isArray(comp.items)) {
83	        this.items.push(...comp.items);
84	      } else {
85	        this.items.push(comp);
86	      }
87	    }
88	  }
89	
90	  /**
91	   * Run the chain. Returns a lazy iterable: the tokenizer is not even started
92	   * until the caller pulls the first token.
93	   * @param {unknown} value
94	   * @param {object} [opts] forwarded to the tokenizer and to every filter
95	   * @returns {Iterable<Token>}
96	   */
97	  analyze(value, opts = {}) {
98	    const items = this.items;
99	    if (!items.length) return [];
100	
101	    const head = items[0];
102	    let gen;
103	    if (typeof head.tokenize === 'function') {
104	      gen = head.tokenize(value, opts);
105	    } else if (typeof head.analyze === 'function') {
106	      // Tolerate an analyzer used as the head of the chain.
107	      gen = head.analyze(value, opts);
108	    } else {
109	      return [];
110	    }
111	
112	    for (let i = 1; i < items.length; i += 1) {
113	      const item = items[i];
114	      if (item && typeof item.filter === 'function') {
115	        gen = item.filter(gen, opts);
116	      }
117	    }
118	    return gen;
119	  }
120	
121	  /** Reset every stage (Whoosh's `CompositeAnalyzer.clean`). */
122	  clean() {
123	    for (const item of this.items) {
124	      if (item && typeof item.clean === 'function') item.clean();
125	    }
126	  }
127	
128	  /** True if any stage performs morphology (stemming). */
129	  has_morph() {
130	    return this.items.some((item) => item && typeof item.has_morph === 'function' && item.has_morph());
131	  }
132	}
133	
134	/**
135	 * Port of `whoosh.analysis.analyzers.StandardAnalyzer` - the default analyzer of
136	 * the `TEXT` field type.
137	 *
138	 * Chain, in order:
139	 *   RegexTokenizer(DEFAULT_WORD_PATTERN, gaps=false)
140	 *     -> LowercaseFilter()
141	 *     -> StopFilter({stoplist: STOP_WORDS, minsize: 2, maxsize: null})
142	 *
143	 * There is NO stemming here (that is `StemmingAnalyzer`). Passing
144	 * `stoplist: null` drops the StopFilter stage ENTIRELY rather than using an empty
145	 * stop list, because an empty stop list would still apply `minsize`.
146	 *
147	 * @param {object} [opts]
148	 * @param {RegExp|string} [opts.expression] token pattern
149	 * @param {Iterable<string>|null} [opts.stoplist] null => no StopFilter at all
150	 * @param {number} [opts.minsize] default 2
151	 * @param {number|null} [opts.maxsize] default null (no upper bound)
152	 * @param {boolean} [opts.gaps] treat the expression as separators
153	 * @returns {CompositeAnalyzer}
154	 */
155	export function StandardAnalyzer(opts = {}) {
156	  const {
157	    expression = DEFAULT_WORD_PATTERN,
158	    stoplist = STOP_WORDS,
159	    minsize = 2,
160	    maxsize = null,
161	    gaps = false,
162	  } = opts || {};
163	
164	  const stages = [new RegexTokenizer(expression, gaps), new LowercaseFilter()];
165	  if (stoplist !== null && stoplist !== undefined) {
166	    stages.push(new StopFilter({ stoplist, minsize, maxsize }));
167	  }
168	  return new CompositeAnalyzer(...stages);
169	}
170	
171	/**
172	 * Port of `whoosh.analysis.analyzers.SimpleAnalyzer`:
173	 * RegexTokenizer -> LowercaseFilter. No stop words, no minimum size, so single
174	 * characters survive.
175	 *
176	 * @param {object} [opts]
177	 * @param {RegExp|string} [opts.expression]
178	 * @param {boolean} [opts.gaps]
179	 * @returns {CompositeAnalyzer}
180	 */
181	export function SimpleAnalyzer(opts = {}) {
182	  const { expression = DEFAULT_WORD_PATTERN, gaps = false } = opts || {};
183	  return new CompositeAnalyzer(new RegexTokenizer(expression, gaps), new LowercaseFilter());
184	}
185	
186	/**
187	 * Port of `whoosh.analysis.analyzers.IDAnalyzer` - the default analyzer of the
188	 * `ID` field type.
189	 *
190	 * Just an IDTokenizer: the whole value becomes one verbatim term, so an ID field
191	 * is findable only by its exact full string. `lowercase: true` appends a
192	 * LowercaseFilter (mirror that on the query side if you use it), which is the
193	 * only way to get case-insensitive IDs.
194	 *
195	 * @param {object} [opts]
196	 * @param {boolean} [opts.lowercase] append a LowercaseFilter
197	 * @returns {CompositeAnalyzer}
198	 */
199	export function IDAnalyzer(opts = {}) {
200	  const { lowercase = false } = opts || {};
201	  const stages = [new IDTokenizer()];
202	  if (lowercase) stages.push(new LowercaseFilter());
203	  return new CompositeAnalyzer(...stages);
204	}
205	
206	/**
207	 * Port of `whoosh.analysis.analyzers.KeywordAnalyzer` - the default analyzer of
208	 * the `KEYWORD` field type.
209	 *
210	 * Splits on spaces/tabs/CR/LF only (or on commas when `commas: true`, with the
211	 * pieces trimmed), and by default does NOT lowercase and does NOT remove stop
212	 * words.
213	 *
214	 * @param {object} [opts]
215	 * @param {boolean} [opts.lowercase] append a LowercaseFilter
216	 * @param {boolean} [opts.commas] split on ',' instead of whitespace
217	 * @returns {CompositeAnalyzer}
218	 */
219	export function KeywordAnalyzer(opts = {}) {
220	  const { lowercase = false, commas = false } = opts || {};
221	  // Whoosh: CommaSeparatedTokenizer is RegexTokenizer(r"[^,]+") | StripFilter().
222	  // We fold the strip into the pattern so no extra filter class is needed.
223	  const tokenizer = commas
224	    ? new RegexTokenizer(/[^,\s](?:[^,]*[^,\s])?/, false)
225	    : new SpaceSeparatedTokenizer();
226	  const stages = [tokenizer];
227	  if (lowercase) stages.push(new LowercaseFilter());
228	  return new CompositeAnalyzer(...stages);
229	}
