1	/**
2	 * Port of `whoosh.analysis.acore.Token`.
3	 *
4	 * In Whoosh a Token is a tiny mutable attribute bag that travels down the
5	 * analysis pipeline (tokenizer -> filter -> filter -> ...). Whoosh's tokenizers
6	 * create ONE Token object and re-`yield` that same object for every token in the
7	 * stream, purely as a speed optimization; consumers are expected to read the
8	 * attributes they care about before pulling the next token.
9	 *
10	 * DELIBERATE DIFFERENCE FROM WHOOSH (documented, as requested):
11	 * our tokenizers allocate a FRESH Token per token instead of recycling a single
12	 * instance. That means an analysis stream can safely be materialized
13	 * (`[...analyzer.analyze(text)]`) without every element collapsing onto the same
14	 * object - the classic Whoosh footgun. Filters still mutate the token they were
15	 * handed and re-yield it (as Whoosh does), which is safe precisely because each
16	 * token is already its own object.
17	 *
18	 * Attribute meanings (same names as Whoosh, snake_case preserved):
19	 *   text        - the token's current text (filters rewrite this)
20	 *   original    - the pre-filter text, only populated when keeporiginal=true
21	 *   boost       - per-token boost, 1.0 unless a filter changes it
22	 *   pos         - token position index (only meaningful when positions=true)
23	 *   startchar   - start offset of the token in the source string (chars=true)
24	 *   endchar     - end offset of the token in the source string (chars=true)
25	 *   stopped     - true when a StopFilter matched this token but was told not to
26	 *                 remove it (removestops=false)
27	 *   positions   - whether the pipeline was asked to track positions
28	 *   chars       - whether the pipeline was asked to track character offsets
29	 *   removestops - whether stop words should be dropped (vs. flagged)
30	 *   mode        - 'index' / 'query' / '' - lets filters behave differently at
31	 *                 index time vs. query time
32	 *
33	 * Offsets are UTF-16 code-unit offsets (JS string indices). They are internally
34	 * consistent but are NOT comparable to Python character offsets for text
35	 * containing astral-plane characters.
36	 */
37	export class Token {
38	  /**
39	   * @param {object} [fields] initial attribute values. Mirrors Whoosh's
40	   *   `Token(positions, chars, removestops=..., mode=..., **kwargs)`: any extra
41	   *   keys are copied straight onto the token, so callers can smuggle custom
42	   *   attributes through the pipeline. `undefined` values are ignored so they
43	   *   never clobber a default.
44	   */
45	  constructor(fields = {}) {
46	    this.text = '';
47	    this.original = null;
48	    this.boost = 1.0;
49	    this.pos = null;
50	    this.startchar = null;
51	    this.endchar = null;
52	    this.stopped = false;
53	    this.positions = false;
54	    this.chars = false;
55	    this.removestops = true;
56	    this.mode = '';
57	
58	    if (fields !== null && typeof fields === 'object') {
59	      for (const key of Object.keys(fields)) {
60	        const value = fields[key];
61	        if (value !== undefined) this[key] = value;
62	      }
63	    }
64	  }
65	
66	  /**
67	   * Equivalent of Whoosh's `Token.copy()` (a `copy.copy`): a shallow clone that
68	   * keeps the prototype and any extra attributes the caller added.
69	   * @returns {Token}
70	   */
71	  copy() {
72	    const clone = Object.create(Object.getPrototypeOf(this));
73	    Object.assign(clone, this);
74	    return clone;
75	  }
76	
77	  /**
78	   * Debug helper modelled on Whoosh's `Token.__repr__`, which prints every
79	   * attribute currently set on the token.
80	   * @returns {string}
81	   */
82	  toString() {
83	    const parts = [];
84	    for (const key of Object.keys(this)) {
85	      const value = this[key];
86	      parts.push(`${key}=${typeof value === 'string' ? JSON.stringify(value) : String(value)}`);
87	    }
88	    return `Token(${parts.join(', ')})`;
89	  }
90	}
91	
92	export default Token;
