1	/**
2	 * Port of `whoosh.analysis.tokenizers`.
3	 *
4	 * A tokenizer is the head of an analysis pipeline: it turns a raw field value
5	 * into a LAZY stream of {@link Token} objects. Filters (see ./filters.mjs) then
6	 * transform that stream. Nothing is materialized into an array anywhere in the
7	 * chain - every stage is a generator, exactly like Whoosh's generator pipeline.
8	 */
9	
10	import { Token } from './token.mjs';
11	
12	/**
13	 * Source text of Whoosh's `whoosh.analysis.tokenizers.default_pattern`,
14	 * `r"\w+(\.?\w+)*"`, rewritten so that it is CORRECT IN JAVASCRIPT.
15	 *
16	 * Python's `\w` on a `str` means "alphanumeric (per `str.isalnum()`) plus
17	 * underscore", unicode-aware. Measured category coverage: letters (Ll/Lo/Lm/...),
18	 * numbers (Nd/No/Nl) and `_` match; combining marks (Mn), other connector
19	 * punctuation such as U+203F, and emoji (So) do NOT. That is exactly
20	 * `\p{L} | \p{N} | U+005F`, hence `[\p{L}\p{N}_]`. `_` must be listed literally
21	 * because it is Pc, not L, and no other Pc character may be added.
22	 *
23	 * JavaScript's `\w` is `[A-Za-z0-9_]` and STAYS ASCII-only even under the `u`
24	 * flag - it reproduces Python's `re` on BYTES, not on `str`. Using bare `\w`
25	 * here would shred "héllo" into "h"/"llo" and make "世界" vanish entirely: no
26	 * exception, just silently empty or wrong terms on both the index and the query
27	 * side, so round-trip tests would still pass. Hence the property escapes.
28	 *
29	 * The trailing `(?:\.?[\p{L}\p{N}_]+)*` is Whoosh's dot-bridging and is
30	 * load-bearing: "www.example.com", "1.5" and "2.7.1" survive as single tokens,
31	 * a sentence-final dot in "end." is not consumed (the group needs word
32	 * characters AFTER the dot), and "a..b" yields "a" and "b" because only a single
33	 * dot may bridge. Whoosh's group is capturing; we make it non-capturing since
34	 * nothing ever reads it.
35	 */
36	const DEFAULT_WORD_SOURCE = '[\\p{L}\\p{N}_]+(?:\\.?[\\p{L}\\p{N}_]+)*';
