38	/**
39	 * Whoosh's default word pattern as a RegExp.
40	 *
41	 * Flags: `g` (iterate every match, i.e. Python's `re.finditer`) and `u`
42	 * (REQUIRED - it enables `\p{...}` and switches matching to code-point
43	 * semantics so an astral-plane letter counts as one character). Deliberately NOT
44	 * `i`: the tokenizer is case-sensitive and lowercasing is a separate downstream
45	 * filter.
46	 *
47	 * This exported object is a template only. {@link RegexTokenizer} never iterates
48	 * it directly - it compiles a fresh RegExp for every `tokenize()` call, because a
49	 * `g`-flagged RegExp carries mutable `lastIndex` state and sharing it across
50	 * calls (or across two interleaved lazy generators over the same tokenizer)
51	 * would make the second call start mid-string and drop tokens. That stale
52	 * `lastIndex` bug is the classic correctness trap in this port.
53	 *
54	 * @type {RegExp}
55	 */
56	export const DEFAULT_WORD_PATTERN = new RegExp(DEFAULT_WORD_SOURCE, 'gu');
57	
58	/** `SpaceSeparatedTokenizer`'s pattern: Whoosh uses `r"[^ \t\r\n]+"`. */
59	const SPACE_SEPARATED_SOURCE = '[^ \\t\\r\\n]+';
