61	/**
62	 * Coerce any field value to a string without ever throwing. Whoosh asserts the
63	 * value is `unicode`; we are deliberately more forgiving because the CLI must
64	 * never crash on odd input (empty strings, numbers, null, unicode).
65	 * @param {unknown} value
66	 * @returns {string}
67	 */
68	function coerceValue(value) {
69	  if (typeof value === 'string') return value;
70	  if (value === null || value === undefined) return '';
71	  try {
72	    return String(value);
73	  } catch {
74	    return '';
75	  }
76	}
