78	/**
79	 * Normalize a user-supplied expression (RegExp or pattern string) into a
80	 * `{source, flags}` pair that is safe to recompile per call. Always forces `g`,
81	 * adds `u` when the pattern is compatible with it, and drops `y` (sticky would
82	 * break finditer semantics).
83	 * @param {RegExp|string|{source: string, flags?: string}} expression
84	 * @returns {{source: string, flags: string}}
85	 */
86	function compileExpression(expression) {
87	  let source;
88	  let flags = '';
89	
90	  if (expression instanceof RegExp) {
91	    source = expression.source;
92	    flags = expression.flags;
93	  } else if (typeof expression === 'string') {
94	    source = expression;
95	  } else if (expression && typeof expression.source === 'string') {
96	    source = expression.source;
97	    flags = typeof expression.flags === 'string' ? expression.flags : '';
98	  } else {
99	    source = DEFAULT_WORD_SOURCE;
100	    flags = 'gu';
101	  }
102	
103	  // 'g' is mandatory (we iterate with exec); 'y' must go (sticky matching would
104	  // stop at the first non-match instead of scanning forward).
105	  let finalFlags = 'g' + flags.replace(/[gy]/g, '');
106	
107	  if (!finalFlags.includes('u') && !finalFlags.includes('v')) {
108	    const withUnicode = finalFlags + 'u';
109	    try {
110	      new RegExp(source, withUnicode);
111	      finalFlags = withUnicode;
112	    } catch {
113	      // Pattern uses constructs that are illegal under `u` (e.g. a stray
114	      // escape). Keep legacy semantics rather than refusing to tokenize.
115	    }
116	  }
117	
118	  try {
119	    new RegExp(source, finalFlags);
120	  } catch {
121	    // Unusable expression: fall back to the default word pattern instead of
122	    // throwing, so no input can crash the pipeline.
123	    source = DEFAULT_WORD_SOURCE;
124	    finalFlags = 'gu';
125	  }
126	
127	  return { source, flags: finalFlags };
128	}
