130	/**
131	 * Base class for all tokenizers (Whoosh's `Tokenizer`, a `Composable`).
132	 *
133	 * The base itself is the "null" tokenizer: it yields no tokens. Every concrete
134	 * subclass overrides `tokenize()`.
135	 */
136	export class Tokenizer {
137	  /**
138	   * @param {unknown} _value the field value to tokenize
139	   * @param {object} [_opts] pipeline options (see {@link RegexTokenizer#tokenize})
140	   * @returns {Generator<Token>}
141	   */
142	  // eslint-disable-next-line no-unused-vars
143	  *tokenize(_value, _opts = {}) {
144	    // Abstract head of the pipeline: nothing to emit.
145	  }
146	
147	  /**
148	   * Alias for {@link Tokenizer#tokenize}, mirroring Whoosh's callable
149	   * `Composable.__call__` so a tokenizer reads the same as an analyzer.
150	   * @param {unknown} value
151	   * @param {object} [opts]
152	   * @returns {Iterable<Token>}
153	   */
154	  call(value, opts = {}) {
155	    return this.tokenize(value, opts);
156	  }
157	
158	  /**
159	   * A bare tokenizer is a valid analyzer in Whoosh (`IDAnalyzer` is literally
160	   * just `IDTokenizer()`), so expose the canonical analyzer entry point too.
161	   * @param {unknown} value
162	   * @param {object} [opts]
163	   * @returns {Iterable<Token>}
164	   */
165	  analyze(value, opts = {}) {
166	    return this.tokenize(value, opts);
167	  }
168	
169	  /** Whoosh's `Composable.clean()` hook - per-document reset. No-op here. */
170	  clean() {}
171	
172	  /** Whoosh's `has_morph()`: tokenizers never perform morphology. */
173	  has_morph() {
174	    return false;
175	  }
