178	/**
179	 * Port of `whoosh.analysis.tokenizers.RegexTokenizer`.
180	 *
181	 * With `gaps=false` (the default) the regex matches the TOKENS themselves. With
182	 * `gaps=true` the regex matches the SEPARATORS and the text between matches is
183	 * yielded instead (Python's `re.split` behaviour).
184	 */
185	export class RegexTokenizer extends Tokenizer {
186	  /**
187	   * @param {RegExp|string} [expression] token (or, with gaps, separator) pattern
188	   * @param {boolean} [gaps] false: matches are tokens; true: matches are gaps
189	   */
190	  constructor(expression = DEFAULT_WORD_PATTERN, gaps = false) {
191	    super();
192	    const { source, flags } = compileExpression(expression);
193	    /** @type {string} pattern source, recompiled fresh on every tokenize() */
194	    this.source = source;
195	    /** @type {string} flags, always containing `g` (and `u` when possible) */
196	    this.flags = flags;
197	    /** @type {boolean} */
198	    this.gaps = Boolean(gaps);
199	    /**
200	     * Informational copy of the pattern (Whoosh exposes `.expression`). NEVER
201	     * used for iteration - see {@link RegexTokenizer#_matches}.
202	     * @type {RegExp}
203	     */
204	    this.expression = new RegExp(source, flags);
205	  }
206	
207	  /**
208	   * Python `re.finditer` equivalent. Compiles a FRESH RegExp per call so the
209	   * global flag's `lastIndex` is never shared between calls or between two
210	   * concurrently-consumed lazy generators.
211	   * @param {string} text
212	   * @returns {Generator<RegExpExecArray>}
213	   * @private
214	   */
215	  *_matches(text) {
216	    const re = new RegExp(this.source, this.flags);
217	    re.lastIndex = 0;
218	    let match;
219	    while ((match = re.exec(text)) !== null) {
220	      yield match;
221	      if (match[0].length === 0) {
222	        // Zero-width match: advance by one full code point or we would spin
223	        // forever. Whoosh's default pattern cannot match empty, but a custom
224	        // one can, and this pipeline must never hang.
225	        const cp = text.codePointAt(re.lastIndex);
226	        re.lastIndex += cp !== undefined && cp > 0xffff ? 2 : 1;
227	        if (re.lastIndex > text.length) break;
228	      }
229	    }
230	  }
231	
232	  /**
233	   * @param {unknown} value field value; '' / whitespace-only / unicode input is
234	   *   handled without throwing (empty and whitespace-only simply yield nothing)
235	   * @param {object} [opts]
236	   * @param {boolean} [opts.positions] record `token.pos`
237	   * @param {boolean} [opts.chars] record `token.startchar` / `token.endchar`
238	   * @param {number} [opts.start_pos] position of the first token
239	   * @param {number} [opts.start_char] character offset of the start of `value`
240	   * @param {string} [opts.mode] '' | 'index' | 'query'
241	   * @param {boolean} [opts.removestops] false => stop words are flagged, not dropped
242	   * @param {boolean} [opts.keeporiginal] copy the text into `token.original`
243	   * @param {boolean} [opts.tokenize] false => emit the whole value as one token
244	   * @returns {Generator<Token>}
245	   */
246	  *tokenize(value, opts = {}) {
247	    const {
248	      positions = false,
249	      chars = false,
250	      start_pos = 0,
251	      start_char = 0,
252	      mode = '',
253	      removestops = true,
254	      keeporiginal = false,
255	      tokenize = true,
256	    } = opts || {};
257	
258	    const text = coerceValue(value);
259	    const shared = { positions, chars, removestops, mode };
260	
261	    if (!tokenize) {
262	      // Whoosh's `tokenize=False` escape hatch: one token holding everything.
263	      const t = new Token(shared);
264	      t.text = text;
265	      t.original = text;
266	      t.boost = 1.0;
267	      if (positions) t.pos = start_pos;
268	      if (chars) {
269	        t.startchar = start_char;
270	        t.endchar = start_char + text.length;
271	      }
272	      yield t;
273	      return;
274	    }
275	
276	    if (!this.gaps) {
277	      // Default: every regex match is a token.
278	      let pos = 0;
279	      for (const match of this._matches(text)) {
280	        const t = new Token(shared);
281	        t.text = match[0];
282	        t.boost = 1.0;
283	        if (keeporiginal) t.original = t.text;
284	        t.stopped = false;
285	        if (positions) t.pos = start_pos + pos;
286	        if (chars) {
287	          t.startchar = start_char + match.index;
288	          t.endchar = start_char + match.index + match[0].length;
289	        }
290	        pos += 1;
291	        yield t;
292	      }
293	      return;
294	    }
295	
296	    // gaps=true: the matches are separators; yield the text between them.
297	    let prevend = 0;
298	    let pos = start_pos;
299	    for (const match of this._matches(text)) {
300	      const start = prevend;
301	      const end = match.index;
302	      const piece = text.slice(start, end);
303	      if (piece) {
304	        const t = new Token(shared);
305	        t.text = piece;
306	        t.boost = 1.0;
307	        if (keeporiginal) t.original = t.text;
308	        t.stopped = false;
309	        if (positions) {
310	          t.pos = pos;
311	          pos += 1;
312	        }
313	        if (chars) {
314	          t.startchar = start_char + start;
315	          t.endchar = start_char + end;
316	        }
317	        yield t;
318	      }
319	      prevend = match.index + match[0].length;
320	    }
321	
322	    // Trailing gap, if the value did not end with a separator.
323	    if (prevend < text.length) {
324	      const t = new Token(shared);
325	      t.text = text.slice(prevend);
326	      t.boost = 1.0;
327	      if (keeporiginal) t.original = t.text;
328	      t.stopped = false;
329	      if (positions) t.pos = pos;
330	      if (chars) {
331	        t.startchar = start_char + prevend;
332	        t.endchar = start_char + text.length;
333	      }
334	      yield t;
335	    }
336	  }
337	}
