15	import { Token } from './token.mjs';
16	import { STOP_WORDS } from './stopwords.mjs';
17	
18	/**
19	 * Read a token's text defensively. A malformed token must never crash the chain.
20	 * @param {Token} t
21	 * @returns {string}
22	 */
23	function tokenText(t) {
24	  if (!t) return '';
25	  if (typeof t.text === 'string') return t.text;
26	  if (t.text === null || t.text === undefined) return '';
27	  try {
28	    return String(t.text);
29	  } catch {
30	    return '';
31	  }
32	}
