34	/**
35	 * Count CODE POINTS, not UTF-16 code units.
36	 *
37	 * Python's `len()` counts code points, so a single astral-plane character (e.g.
38	 * U+1D400, many CJK extension characters) has length 1 in Python but `.length`
39	 * 2 in JS. Using `.length` for the minsize/maxsize test would keep tokens that
40	 * Whoosh drops.
41	 * @param {string} s
42	 * @returns {number}
43	 */
44	function codePointLength(s) {
45	  let n = 0;
46	  for (let i = 0; i < s.length; i += 1) {
47	    const code = s.charCodeAt(i);
48	    if (code >= 0xd800 && code <= 0xdbff && i + 1 < s.length) {
49	      const next = s.charCodeAt(i + 1);
50	      if (next >= 0xdc00 && next <= 0xdfff) i += 1; // surrogate pair = 1 code point
51	    }
52	    n += 1;
53	  }
54	  return n;
55	}
