165	   * @param {number|null} [options.maxsize] drop tokens longer than this; null/0
166	   *   means no upper bound
167	   * @param {boolean} [options.renumber] keep `token.pos` contiguous
168	   */
169	  constructor({ stoplist = STOP_WORDS, minsize = 2, maxsize = null, renumber = true } = {}) {
170	    super();
171	    /** @type {Set<string>} */
172	    this.stops = new Set();
173	    if (stoplist) {
174	      // Accept a Set, an Array, or any iterable of words (Whoosh: frozenset()).
175	      try {
176	        for (const word of stoplist) {
177	          if (typeof word === 'string') this.stops.add(word);
178	          else if (word !== null && word !== undefined) this.stops.add(String(word));
179	        }
180	      } catch {
181	        // Not iterable - behave as if no stop list had been supplied.
182	      }
183	    }
184	    const min = Number(minsize);
185	    /** @type {number} */
186	    this.min = Number.isFinite(min) ? min : 0;
187	    const max = maxsize === null || maxsize === undefined ? 0 : Number(maxsize);
188	    /** @type {number} 0 means "no upper bound" (Whoosh uses a falsy maxsize) */
189	    this.max = Number.isFinite(max) ? max : 0;
190	    /** @type {boolean} */
191	    this.renumber = Boolean(renumber);
192	  }
193	
194	  /**
195	   * @param {Iterable<Token>} tokenStream
196	   * @param {object} [_opts]
197	   * @returns {Generator<Token>}
198	   */
199	  // eslint-disable-next-line no-unused-vars
200	  *filter(tokenStream, _opts = {}) {
201	    if (!tokenStream) return;
202	
203	    const stops = this.stops;
204	    const minsize = this.min;
205	    const maxsize = this.max;
206	    const renumber = this.renumber;
207	
208	    let pos = null;
209	
210	    for (const t of tokenStream) {
211	      if (!t) continue;
212	      const text = tokenText(t);
213	      const size = codePointLength(text);
214	
215	      if (size >= minsize && (!maxsize || size <= maxsize) && !stops.has(text)) {
216	        // Not a stop word: keep it, closing any positional gap left behind.
217	        if (renumber && t.positions) {
218	          if (pos === null) {
219	            // First survivor keeps its own position (defensively coerced, in
220	            // case a caller asked for positions without supplying any).
221	            pos = typeof t.pos === 'number' ? t.pos : 0;
222	            t.pos = pos;
223	          } else {
224	            pos += 1;
225	            t.pos = pos;
226	          }
227	        }
228	        if (t.stopped) t.stopped = false;
229	        yield t;
230	      } else if (!t.removestops) {
231	        // It IS a stop word, but this pass was told to keep the hole visible.
232	        t.stopped = true;
233	        yield t;
234	      }
235	      // else: dropped entirely.
236	    }
237	  }
